// Mandatory included headers
#include <sink.hpp>
#include <nlohmann/json.hpp>
#include <pugg/Kernel.h>

// other includes as needed here
#include <iostream>
#include <map>
#include <string>
#include <vector>

// Define the name of the plugin
#ifndef PLUGIN_NAME
#define PLUGIN_NAME "csv"
#endif

// Load the namespaces
using namespace std;
using json = nlohmann::json;

// Sink plugin that prints each received message as one CSV line on stdout:
// timestamp, timecode, agent_id, topic, then the fields selected for that
// topic by the JSON pointers in the `fields` setting.
class CsvPlugin : public Sink<json> {

public:
  using Sink::Sink; // inherit constructors

  string kind() override { return PLUGIN_NAME; }

  return_type load_data(json const &input, string topic = "",
                        vector<unsigned char> const *blob = nullptr) override {
    if (!_config_ok) {
      return return_type::critical;
    }
    try {
      string out = format_line(input, topic);
      if (!out.empty()) {
        cout << out << '\n' << flush;
      }
    } catch (exception &e) {
      _error = e.what();
      return return_type::error;
    }
    return return_type::success;
  }

  // Build the CSV output (without trailing newline) for one message: a single
  // line in wide mode; in tidy mode one line per field (empty if the topic has
  // no fields), joined by '\n'.
  string format_line(json const &input, string const &topic) const {
    string head = scalar(find(input, "/timestamp/$date", "/timestamp"));
    head += _separator + scalar(find(input, "/timecode"));
    head += _separator + scalar(find(input, "/agent_id"));
    head += _separator + quote(topic);
    auto it = _fields.find(topic);
    if (!_tidy) {
      if (it != _fields.end()) {
        for (auto const &f : it->second) {
          head += _separator + scalar(find(input, f.second));
        }
      }
      return head;
    }
    string lines;
    if (it != _fields.end()) {
      for (auto const &f : it->second) {
        if (!lines.empty()) lines += '\n';
        lines += head + _separator + quote(f.first) + _separator +
                 scalar(find(input, f.second));
      }
    }
    return lines;
  }

  void set_params(const json &params) override {
    Sink::set_params(params);

    _params["fields"] = json::object();
    _params["separator"] = ",";
    _params["decimal"] = ".";
    _params["header_prefix"] = "";
    _params["tidy"] = true;
    _params.merge_patch(params);

    _config_ok = false;
    _fields.clear();
    try {
      _separator = _params["separator"].get<string>();
      _decimal = _params["decimal"].get<string>();
      _tidy = _params["tidy"].get<bool>();
      if (_separator.empty() || _decimal.empty()) {
        throw invalid_argument("separator and decimal must not be empty");
      }
      if (_separator == _decimal) {
        throw invalid_argument("separator and decimal must differ, both are '" +
                               _separator + "'");
      }
      if (!_params["fields"].is_object()) {
        throw invalid_argument("fields must be a dictionary topic -> pointer(s)");
      }
      for (auto const &[topic, value] : _params["fields"].items()) {
        vector<pair<string, json::json_pointer>> pointers;
        if (value.is_string()) {
          pointers.emplace_back(value.get<string>(),
                                json::json_pointer(value.get<string>()));
        } else if (value.is_array()) {
          for (auto const &v : value) {
            pointers.emplace_back(v.get<string>(),
                                  json::json_pointer(v.get<string>()));
          }
        } else {
          throw invalid_argument("fields['" + topic +
                                 "'] must be a string or an array of strings");
        }
        _fields[topic] = std::move(pointers);
      }
      _config_ok = true;
    } catch (exception &e) {
      _error = string("Invalid settings: ") + e.what();
    }
    // print header line
    if (_config_ok) {
      string header = _params["header_prefix"].get<string>();
      header += "timestamp" + _separator + "timecode" + _separator + "agent_id" +
                _separator + "topic";
      if (_tidy) {
        header += _separator + "field" + _separator + "value";
      } else {
        for (auto const &[topic, pointers] : _fields) {
          for (auto const &f : pointers) {
            header += _separator + f.second.to_string();
          }
        }
      }
      cout << header << '\n' << flush;
    }
  }

  map<string, string> info() override {
    if (!_config_ok) {
      return {{"error", _error}};
    }
    return {{"separator", _separator},
            {"decimal", _decimal},
            {"tidy", _tidy ? "true" : "false"},
            {"topics", to_string(_fields.size())}};
  }

private:
  // Return the value at the first pointer that exists, or nullptr if none.
  json const *find(json const &input, string const &p1, string const &p2 = "") const {
    return find(input, json::json_pointer(p1), p2);
  }

  json const *find(json const &input, json::json_pointer const &ptr,
                   string const &fallback = "") const {
    if (input.contains(ptr)) {
      return &input.at(ptr);
    }
    if (!fallback.empty()) {
      json::json_pointer fb(fallback);
      if (input.contains(fb)) {
        return &input.at(fb);
      }
    }
    return nullptr;
  }

  // NA if missing, NULL if not a scalar, otherwise the formatted value.
  string scalar(json const *v) const {
    if (v == nullptr) {
      return "NA";
    }
    if (v->is_number()) {
      string s = v->dump();
      if (_decimal != ".") {
        auto pos = s.find('.');
        if (pos != string::npos) {
          s.replace(pos, 1, _decimal);
        }
      }
      return s;
    }
    if (v->is_boolean()) {
      return v->get<bool>() ? "true" : "false";
    }
    if (v->is_string()) {
      return quote(v->get<string>());
    }
    return "NULL";
  }

  // RFC 4180 quoting, only when needed.
  string quote(string const &s) const {
    if (s.find_first_of("\"\r\n") == string::npos &&
        s.find(_separator) == string::npos) {
      return s;
    }
    string q = "\"";
    for (char c : s) {
      if (c == '"') q += '"';
      q += c;
    }
    return q + "\"";
  }

  map<string, vector<pair<string, json::json_pointer>>> _fields;
  string _separator = ",";
  string _decimal = ".";
  bool _tidy = true;
  bool _config_ok = false;
};



